<?php
declare(strict_types=1);
foreach(['DB_HOST','DB_PORT','DB_NAME','DB_USER','DB_PASS'] as $key){$value=getenv($key);if($value!==false)$_ENV[$key]=$value;}
use App\Core\Database; use App\Core\Request; use App\Services\ChargeCategoryService; use App\Services\StudentChargeService;
require dirname(__DIR__,2).'/vendor/autoload.php';
if(getenv('MIRANDA_FINANCE_TEST')!=='1'||!preg_match('/^miranda_finance_data_test_/',(string)getenv('DB_NAME'))){fwrite(STDERR,"Refusing unsafe database.\n");exit(2);}
if(($argv[1]??'')==='--worker'){[$school,$student,$year,$category]=array_map('intval',array_slice($argv,2));Request::set('auth_user',['role'=>'admin','school_id'=>$school]);$r=(new StudentChargeService())->create(['student_id'=>$student,'charge_category_id'=>$category,'academic_year_id'=>$year,'year_value'=>2027,'billing_month'=>1,'original_amount'=>250,'operation_key'=>'retry-safe-operation']);if(isset($r['error'])){fwrite(STDERR,$r['error']);exit(1);}exit(0);}
function ok(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);} $pdo=Database::connect();$x=(string)getmypid();$pdo->prepare('INSERT INTO schools(name,code,slug,email_domain)VALUES(?,?,?,?)')->execute(['Idempotency '.$x,'ID'.$x,'idempotency-'.$x,'id'.$x.'.test']);$school=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO academic_years(school_id,label,name,status,is_current)VALUES(?,?,?,"ACTIVE",1)')->execute([$school,'2026/2027','2026/2027']);$year=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO students(school_id,first_name,last_name,class_level,monthly_amount,status)VALUES(?,?,?,?,?,"REGISTERED")')->execute([$school,'Retry','Student','Test',0]);$student=(int)$pdo->lastInsertId();Request::set('auth_user',['role'=>'admin','school_id'=>$school]);(new ChargeCategoryService())->all(true);$q=$pdo->prepare('SELECT id FROM charge_categories WHERE school_id=? AND code="TRANSPORT"');$q->execute([$school]);$category=(int)$q->fetchColumn();$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__FILE__).' --worker '.$school.' '.$student.' '.$year.' '.$category;$pipes=[];$a=proc_open($cmd,[1=>['pipe','w'],2=>['pipe','w']],$pipes);$pipes2=[];$b=proc_open($cmd,[1=>['pipe','w'],2=>['pipe','w']],$pipes2);$sa=proc_close($a);$sb=proc_close($b);ok($sa===0&&$sb===0,'Concurrent workers did not return an application success');$q=$pdo->prepare('SELECT COUNT(*) FROM student_financial_items WHERE school_id=? AND student_id=?');$q->execute([$school,$student]);ok((int)$q->fetchColumn()===1,'Concurrent retry created duplicate obligation');$q=$pdo->prepare('SELECT COUNT(*) FROM payments WHERE school_id=? AND student_id=?');$q->execute([$school,$student]);ok((int)$q->fetchColumn()===0,'Retry created payment');echo "financial idempotency integration: OK\n";
